const canvas=document.getElementById('map'),ctx=canvas.getContext('2d');
const W=30,H=18,T=35, names=['Highmere','Redwyne','Ashenfort','Dunwold','Stormwatch','Everwold','Blackfen','Goldcrest','Thornwall','Westmark','Kingsfall'];
const factions=[{name:'Highmere',color:'#53846a',dark:'#315b45',light:'#a1c38e',player:true},{name:'Redwyne',color:'#c56e5b',dark:'#8c453b',light:'#e6a18a'},{name:'Ashenfort',color:'#6481a4',dark:'#3f587c',light:'#a3b8d0'},{name:'Dunwold',color:'#b18a4d',dark:'#7d6235',light:'#d7bb79'}];
let tiles=[],turn=1,selected=0,mode='',logs=[],gameOver=false,toastTimer;
let treasury={gold:74,food:55},realmNames=factions.map(f=>f.name);
const at=(x,y)=>y*W+x, xy=i=>[i%W,Math.floor(i/W)], neighbors=i=>{const [x,y]=xy(i);return [[x+1,y],[x-1,y],[x,y+1],[x,y-1]].filter(([a,b])=>a>=0&&a<W&&b>=0&&b<H).map(([a,b])=>at(a,b))};
function rand(n){return Math.floor(Math.random()*n)}
function init(){
 tiles=Array.from({length:W*H},(_,i)=>{let r=Math.random(),terrain=r<.09?'water':r<.28?'forest':r<.47?'hill':r<.54?'ruins':'meadow';return {terrain,owner:-1,building:'',swords:0,spears:0,capital:false,name:''}});
 // Make generous traversable channels, then seed four separated kingdoms.
 for(let y=0;y<H;y++)for(let x=0;x<W;x++){let t=tiles[at(x,y)];if(t.terrain==='water'&&Math.random()<.48)t.terrain='meadow'}
 const starts=[[3,3],[26,3],[3,14],[26,14]];
 starts.forEach(([x,y],f)=>{let cap=at(x,y),tile=tiles[cap];tile.owner=f;tile.capital=true;tile.building='capital';tile.name=names[f];tile.swords=f===0?10:9;tile.spears=f===0?8:7;
  neighbors(cap).filter(i=>tiles[i].terrain!=='water').slice(0,3).forEach(i=>{tiles[i].owner=f;tiles[i].building=Math.random()<.35?'farm':''});
 });
 selected=at(3,3);turn=1;treasury={gold:74,food:55};logs=[];gameOver=false;addLog('Your banner rises over Highmere Keep. The frontier is yours to shape.');addLog('Redwyne, Ashenfort, and Dunwold are gathering strength.');render();
}
function addLog(text){logs.unshift(text);logs=logs.slice(0,12);renderLog()}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function current(){return tiles[selected]}
function ownedCount(owner){return tiles.filter(t=>t.owner===owner).length}
function income(owner=0){let gold=0,food=0;tiles.forEach(t=>{if(t.owner!==owner)return;gold+=t.building==='capital'?3:t.building==='market'?3:1;food+=t.building==='capital'?2:t.building==='farm'?3:1});let units=tiles.reduce((n,t)=>n+(t.owner===owner?t.swords+t.spears:0),0);return {gold,food:food-Math.ceil(units/12)}}
function terrainLabel(t){return ({meadow:'Meadow',forest:'Forest',hill:'Highland',ruins:'Old ruins',water:'Deep water'})[t]}
function emoji(t){return ({meadow:'🌱',forest:'🌲',hill:'⛰️',ruins:'🪨',water:'🌊'})[t.terrain]}
function setMode(m){mode=m;document.querySelectorAll('.action').forEach(b=>b.classList.remove('active'));let id={claim:'claimBtn',move:'moveBtn',attack:'attackBtn'}[m];if(id)document.getElementById(id).classList.add('active');let msg={claim:'Choose a neutral tile next to your border to claim it for 12 gold.',move:'Choose an adjacent territory to march your troops there.',attack:'Choose a neighboring rival territory to begin a battle.'};document.getElementById('hint').textContent=msg[m]||'Choose an action for this territory, or inspect another tile.'}
function render(){drawMap();updatePanel();updateEconomy();renderLog()}
function updateEconomy(){let inc=income();document.getElementById('gold').textContent=treasury.gold;document.getElementById('food').textContent=treasury.food;document.getElementById('goldRate').textContent=`+${inc.gold} / turn`;document.getElementById('foodRate').textContent=`${inc.food>=0?'+':''}${inc.food} / turn`;document.getElementById('landCount').textContent=ownedCount(0);document.getElementById('realmCount').textContent=`${new Set(tiles.filter(t=>t.owner>0).map(t=>t.owner)).size} rivals`;document.getElementById('season').textContent=`${['Spring','Summer','Autumn','Winter'][(turn-1)%4]} · Year ${Math.ceil(turn/4)}`;document.getElementById('mobileStatus').textContent=`Your move · Year ${Math.ceil(turn/4)}`}
function updatePanel(){let t=current(),owner=t.owner,owned=owner===0,enemy=owner>0;document.getElementById('inspectHeading').textContent=owned?'Your Command':enemy?factions[owner].name:'Frontier';document.getElementById('ownershipLabel').textContent=owned?'YOUR REALM':enemy?'RIVAL REALM':'UNCLAIMED';document.getElementById('ownershipLabel').style.color=owned?'#477755':enemy?factions[owner].dark:'#98743c';document.getElementById('tileEmoji').textContent=t.capital?'🏰':emoji(t);document.getElementById('tileName').textContent=t.name||`${terrainLabel(t.terrain)} territory`;document.getElementById('tileSub').textContent=t.capital?`${factions[owner]?.name||'Lost'} capital · ${terrainLabel(t.terrain)}`:owner<0?`Unclaimed · ${terrainLabel(t.terrain)}`:`${factions[owner]?.name||'Realm'} · ${terrainLabel(t.terrain)}`;document.getElementById('terrainText').textContent=terrainLabel(t.terrain);document.getElementById('buildingText').textContent=t.building?({capital:'Capital',farm:'Farm',market:'Market',camp:'Training ground'})[t.building]:'Wilderness';document.getElementById('swordCount').textContent=t.swords;document.getElementById('spearCount').textContent=t.spears;
 const hasAdj=neighbors(selected).some(i=>tiles[i].owner===0),gold=treasury.gold;const disable=(id,v)=>document.getElementById(id).disabled=v;
 disable('claimBtn',!owned||!hasAdj||gold<12);disable('moveBtn',!owned||(t.swords+t.spears<2));disable('attackBtn',!owned||(t.swords+t.spears<2)||!neighbors(selected).some(i=>tiles[i].owner>0));disable('farmBtn',!owned||!!t.building||gold<18||t.terrain==='water');disable('mineBtn',!owned||!!t.building||gold<22||t.terrain==='water');disable('campBtn',!owned||!!t.building||gold<25||t.terrain==='water');disable('recruitSword',!owned||gold<16||t.terrain==='water');disable('recruitSpear',!owned||gold<14||t.terrain==='water');
}

