function drawMap(){
 ctx.clearRect(0,0,canvas.width,canvas.height);
 for(let i=0;i<tiles.length;i++){const t=tiles[i],[x,y]=xy(i),px=x*T,py=y*T;let base={meadow:'#dce4cb',forest:'#c6d5bd',hill:'#d7d2b9',ruins:'#d9d4c3',water:'#a9c8c8'}[t.terrain];ctx.fillStyle=base;ctx.fillRect(px,py,T,T);
  // soft terrain marks keep every tile legible while making the world feel lived-in
  ctx.globalAlpha=.34;ctx.fillStyle=t.terrain==='water'?'#6eaaa9':t.terrain==='hill'?'#a49368':t.terrain==='forest'?'#638362':t.terrain==='ruins'?'#8f8b79':'#879b69';
  const seed=(i*19+11)%29;if(t.terrain==='forest'){for(let k=0;k<2;k++){let ox=6+((seed+k*11)%23),oy=8+((seed*3+k*13)%20);ctx.beginPath();ctx.arc(px+ox,py+oy,3.8,0,Math.PI*2);ctx.fill()}}else if(t.terrain==='hill'){ctx.beginPath();ctx.moveTo(px+7,py+26);ctx.lineTo(px+17,py+8+seed%5);ctx.lineTo(px+27,py+26);ctx.fill()}else if(t.terrain==='water'){ctx.strokeStyle='#679c9a';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(px+7,py+13+seed%7);ctx.quadraticCurveTo(px+17,py+9,px+27,py+14+seed%7);ctx.stroke()}else{ctx.beginPath();ctx.arc(px+8+seed%21,py+8+(seed*2)%21,1.3,0,7);ctx.fill()}ctx.globalAlpha=1;
  if(t.owner>=0){ctx.fillStyle=factions[t.owner].color;ctx.globalAlpha=t.owner===0?.34:.32;ctx.fillRect(px+1,py+1,T-2,T-2);ctx.globalAlpha=1;ctx.strokeStyle=factions[t.owner].color;ctx.lineWidth=1.5;ctx.strokeRect(px+1.5,py+1.5,T-3,T-3)}
  if(t.capital){ctx.fillStyle=factions[t.owner].dark;ctx.beginPath();ctx.arc(px+T/2,py+T/2,10,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff4d8';ctx.font='bold 13px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('✦',px+T/2,py+T/2+.5)}
  else if(t.swords+t.spears>0){ctx.fillStyle=factions[t.owner]?.dark||'#3d4d40';ctx.beginPath();ctx.arc(px+T-8,py+8,8,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.font='bold 9px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(Math.min(99,t.swords+t.spears),px+T-8,py+8)}
  if(t.building==='farm'&&!t.capital){ctx.font='10px sans-serif';ctx.textAlign='left';ctx.textBaseline='bottom';ctx.fillText('🌾',px+2,py+T-1)}else if(t.building==='market'){ctx.font='10px sans-serif';ctx.textAlign='left';ctx.textBaseline='bottom';ctx.fillText('✧',px+2,py+T-2)}else if(t.building==='camp'){ctx.font='10px sans-serif';ctx.textAlign='left';ctx.textBaseline='bottom';ctx.fillText('⚑',px+2,py+T-2)}
  ctx.strokeStyle='#526c5830';ctx.lineWidth=.6;ctx.strokeRect(px+.3,py+.3,T-.6,T-.6);
 }
 const [sx,sy]=xy(selected);ctx.strokeStyle='#f9c95f';ctx.lineWidth=3;ctx.strokeRect(sx*T+2,sy*T+2,T-4,T-4);ctx.strokeStyle='#fff4c6';ctx.lineWidth=1;ctx.strokeRect(sx*T+4,sy*T+4,T-8,T-8);
}
